    68  function TabSelector({state, navigation, onTabPress = () => {}, position, onFocusTrapContainerElementChanged}: TabSelectorProps) {
    69      const {translate} = useLocalize();
    70      const theme = useTheme();
    71      const styles = useThemeStyles();
    72      const defaultAffectedAnimatedTabs = useMemo(() => Array.from({length: state.routes.length}, (v, i) => i), [state.routes.length]);
    73      const [affectedAnimatedTabs, setAffectedAnimatedTabs] = useState(defaultAffectedAnimatedTabs);
    74
    75      const getBackgroundColor = useCallback(
    76          (routesLength: number, tabIndex: number, affectedTabs: number[]) => {
    77              if (routesLength > 1) {
    78                  const inputRange = Array.from({length: routesLength}, (v, i) => i);
    79
    80                  return position.interpolate({
    81                      inputRange,
    82                      outputRange: inputRange.map((i) => (affectedTabs.includes(tabIndex) && i === tabIndex ? theme.border : theme.appBG)),
    83                  }) as unknown as Animated.AnimatedInterpolation<string>;
    84              }
    85              return theme.border;
    86          },
    87          [theme, position],
    88      );
    89
    90      useEffect(() => {
    91          // It is required to wait transition end to reset affectedAnimatedTabs because tabs style is still animating during transition.
    92          setTimeout(() => {
    93              setAffectedAnimatedTabs(defaultAffectedAnimatedTabs);
    94          }, CONST.ANIMATED_TRANSITION);
    95      }, [defaultAffectedAnimatedTabs, state.index]);
    96
    97      return (
    98          <FocusTrapContainerElement onContainerElementChanged={onFocusTrapContainerElementChanged}>
    99              <View style={styles.tabSelector}>
   100                  {state.routes.map((route, index) => {
   101                      const activeOpacity = getOpacity(position, state.routes.length, index, true, affectedAnimatedTabs);
   102                      const inactiveOpacity = getOpacity(position, state.routes.length, index, false, affectedAnimatedTabs);
   103                      const backgroundColor = getBackgroundColor(state.routes.length, index, affectedAnimatedTabs);
   104                      const isActive = index === state.index;
   105                      const {icon, title} = getIconAndTitle(route.name, translate);
   106
   107                      const onPress = () => {
   108                          if (isActive) {
   109                              return;
   110                          }
   111
   112                          setAffectedAnimatedTabs([state.index, index]);
   113
   114                          const event = navigation.emit({
   115                              type: 'tabPress',
   116                              target: route.key,
   117                              canPreventDefault: true,
   118                          });
   119
   120                          if (!event.defaultPrevented) {
   121                              // The `merge: true` option makes sure that the params inside the tab screen are preserved
   122                              navigation.navigate({key: route.key, merge: true});
   123                          }
   124
   125                          onTabPress(route.name);
   126                      };
   127
   128                      return (
   129                          <TabSelectorItem
   130                              key={route.name}
   131                              icon={icon}
   132                              title={title}
   133                              onPress={onPress}
   134                              activeOpacity={activeOpacity}
   135                              inactiveOpacity={inactiveOpacity}
   136                              backgroundColor={backgroundColor}
   137                          />
   138                      );
   139                  })}
   140              </View>
   141          </FocusTrapContainerElement>
   142      );
   143  }
